const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function check(r) {
  const parts = [
    ['path', r.path],
    ['userinfo', r.authority && r.authority.userinfo],
    ['host', r.authority && r.authority.host],
    ['query', r.query],
    ['fragment', r.fragment],
