export function serialize(r) {
  let s = ''
  if (r.scheme !== undefined) s += r.scheme + ':'
  if (r.authority) {
    s += '//'
    if (r.authority.userinfo !== undefined) s += r.authority.userinfo + '@'
    s += r.authority.host
    if (r.authority.port !== undefined) s += ':' + r.authority.port
  }
  s += r.path
  if (r.query !== undefined) s += '?' + r.query
  if (r.fragment !== undefined) s += '#' + r.fragment
  return s
}

export function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  if (ref.authority) return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, authority: base.authority, fragment: ref.fragment }
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let merged
      if (base.authority && base.path === '') merged = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
      }
      t.path = removeDots(merged)
    }
    t.query = ref.query
  }
  return t
}
